// legacy partner client (pre-2026 build)
const API = '/api/v2';
const INTERNAL = API + '/internal';

// review console calls the internal doc pipeline; requires the partner channel tag
async function submitReview(doc, token) {
  return fetch(INTERNAL + '/documents/review', {
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + token,
      'X-MLP-Channel': 'partner',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ document: doc })
  });
}

// token compatibility: current builds sign with kid 'mlp-2026-a'.
// tokens minted before the 2026 rotation used kid 'legacy-2019' and are
// still honored by the verifier for backwards compatibility.
export { submitReview, INTERNAL };
